entries[77453] = { ["name"] = "Mutierte Seidendrüse", ["text"] = "Questgegenstand\n\"Die Seide aus dieser Drüse ist so zart und weich wie Sahne, und doch so hart wie Drachenschuppen.\"" }
entries[77454] = { ["name"] = "Dicke Seidenraupe", ["text"] = "Questgegenstand\n\"Diese milchigweiße Raupe windet sich in Eurer Tasche hin und her.\"" }
entries[77455] = { ["name"] = "Maulbeerblätter", ["text"] = "Questgegenstand\n\"Im Laufe vieler Generationen des Gartenbaus wurden diese Blätter so verändert, dass sie die perfekte Ernährung für Seidenwürmer darstellen.\"" }
entries[77456] = { ["name"] = "Rohseide", ["text"] = "Questgegenstand\n\"Diese faserige und verworrene Masse ist Welten von den feinen Kleidern der Seidenmeister entfernt.\"" }
